// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract PaymentProcessor {
    address public owner;
    mapping(address => uint256) public balances;
    mapping(address => uint256) public lastWithdrawal;
    mapping(address => uint8) public retryCount;
    mapping(address => bool) public isWhitelisted;

    uint256 public constant RATE_LIMIT_WINDOW = 1 hours;
    uint256 public constant MAX_RETRIES = 3;
    uint256 public constant MAX_WITHDRAWAL = 5 ether;

    event PaymentProcessed(address indexed recipient, uint256 amount);
    event RetryAttempt(address indexed recipient, uint8 attempt);
    event RateLimitReset(address indexed user);
    event TransferFailed(address indexed recipient, uint256 amount);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier rateLimited(address user) {
        require(
            block.timestamp >= lastWithdrawal[user] + RATE_LIMIT_WINDOW ||
            lastWithdrawal[user] == 0,
            "Rate limited"
        );
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function deposit() external payable {
        require(msg.value > 0, "Zero deposit");
        balances[msg.sender] += msg.value;
    }

    function whitelistAddress(address user) external onlyOwner {
        isWhitelisted[user] = true;
    }

    function removeFromWhitelist(address user) external onlyOwner {
        isWhitelisted[user] = false;
    }

    function processPayment(address payable recipient, uint256 amount) 
        external 
        rateLimited(recipient)
    {
        require(isWhitelisted[msg.sender], "Not whitelisted");
        require(amount <= MAX_WITHDRAWAL, "Exceeds max");
        require(balances[recipient] >= amount, "Insufficient balance");

        balances[recipient] -= amount;
        lastWithdrawal[recipient] = block.timestamp;
        retryCount[recipient] = 0;

        _executeTransfer(recipient, amount);
    }

    function _executeTransfer(address payable recipient, uint256 amount) internal {
        (bool success, ) = recipient.call{value: amount, gas: 2300}("");

        if (!success) {
            _handleFailedTransfer(recipient, amount);
        } else {
            emit PaymentProcessed(recipient, amount);
        }
    }

    function _handleFailedTransfer(address payable recipient, uint256 amount) internal {
        retryCount[recipient]++;
        emit RetryAttempt(recipient, retryCount[recipient]);

        if (retryCount[recipient] < MAX_RETRIES) {
            (bool retrySuccess, ) = recipient.call{value: amount, gas: 2300}("");
            if (retrySuccess) {
                emit PaymentProcessed(recipient, amount);
            } else {
                _handleFailedTransfer(recipient, amount);
            }
        } else {
            // Refund balance on permanent failure
            balances[recipient] += amount;
            emit TransferFailed(recipient, amount);
        }
    }

    function emergencyWithdraw() external onlyOwner {
        payable(owner).transfer(address(this).balance);
    }

    function getContractBalance() external view returns (uint256) {
        return address(this).balance;
    }

    function resetRateLimit(address user) external onlyOwner {
        lastWithdrawal[user] = 0;
        retryCount[user] = 0;
        emit RateLimitReset(user);
    }
}
